import 'package:flutter/material.dart';

class SFormSection extends StatelessWidget { const SFormSection({super.key, required this.title, required this.child, this.description}); final String title; final String? description; final Widget child; @override Widget build(BuildContext context) => Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(title, style: Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight: FontWeight.w700)), if (description != null) Padding(padding: const EdgeInsets.only(top: 4, bottom: 12), child: Text(description!)), child]); }
class SFormRow extends StatelessWidget { const SFormRow({super.key, required this.children}); final List<Widget> children; @override Widget build(BuildContext context) => Column(children: [for (var i = 0; i < children.length; i++) Padding(padding: EdgeInsets.only(bottom: i == children.length - 1 ? 0 : 12), child: children[i])]); }
class SSelectField<T> extends StatelessWidget { const SSelectField({super.key, required this.value, required this.items, required this.onChanged, this.label, this.hint}); final T? value; final List<DropdownMenuItem<T>> items; final ValueChanged<T?> onChanged; final String? label, hint; @override Widget build(BuildContext context) => DropdownButtonFormField<T>(value: value, items: items, onChanged: onChanged, decoration: InputDecoration(labelText: label, hintText: hint, filled: true, fillColor: const Color(0xFFFCE8EB), border: OutlineInputBorder(borderRadius: BorderRadius.circular(14), borderSide: BorderSide.none))); }
